{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "orders",
      "host": "orders.internal",
      "port": 7470,
      "weight": 5,
      "health_check": "/healthz"
    },
    {
      "name": "inventory",
      "host": "inventory.internal",
      "port": 8438,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "payments",
      "host": "payments.internal",
      "port": 7323,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 7051,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 8943,
      "weight": 2,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/carts/labels",
      "upstream": "carts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 3000,
      "retries": 0
    },
    {
      "path": "/api/v1/orders/labels",
      "upstream": "orders",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/inventory/refunds",
      "upstream": "inventory",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 2
    },
    {
      "path": "/api/v1/inventory/events",
      "upstream": "inventory",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 0
    },
    {
      "path": "/api/v1/search/batch",
      "upstream": "search",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/inventory/lookup",
      "upstream": "inventory",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 3000,
      "retries": 2
    },
    {
      "path": "/api/v1/payments/refunds",
      "upstream": "payments",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 3000,
      "retries": 1
    },
    {
      "path": "/api/v1/orders/export",
      "upstream": "orders",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/payments/labels",
      "upstream": "payments",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 0
    }
  ]
}

